TD.add("backend-architecture", [

{t:"API", a:"Application Programming Interface", d:"A defined contract through which one piece of software talks to another.", l:"core", g:["fundamentals","integration"],
 b:["An API specifies what operations are available, what inputs they take, what they return and what errors they can produce. That contract lets the implementation change freely behind it — which is the whole point, and why breaking an API is treated so seriously.",
    "The term spans several scopes: a library's public functions, an operating system's system calls, a REST or GraphQL endpoint over HTTP. The design principles are the same at every scale: make the common case easy, make the contract explicit, and version it so consumers are never broken without warning."],
 k:["A contract, not an implementation — the implementation must stay free to change.",
    "Design for the caller, not for the convenience of the internals.",
    "Breaking changes require versioning and a deprecation period.",
    "Document errors as carefully as successes."],
 dg:"request-response",
 r:["REST","GraphQL","gRPC","API Gateway","API Versioning"]},

{t:"REST", a:"Representational State Transfer", d:"An architectural style for web APIs built around resources, HTTP verbs and stateless requests.", l:"core", g:["api","architecture"],
 b:["REST models the domain as resources identified by URLs — `/orders/123` — and uses HTTP methods for operations: GET reads, POST creates, PUT replaces, PATCH updates, DELETE removes. Each request carries everything needed to process it, so the server keeps no client session state between calls.",
    "Its strengths are ubiquity, cacheability and the fact that every tool and proxy already understands it. Its weaknesses are over-fetching (endpoints return fixed shapes) and under-fetching (rendering one screen takes several round trips), which is exactly the gap GraphQL was created to fill."],
 k:["Resources as nouns in URLs; HTTP methods as the verbs.",
    "Stateless: every request carries its own context.",
    "GET, PUT and DELETE must be idempotent; POST need not be.",
    "Over-fetching and under-fetching are its structural weaknesses."],
 x:{lang:"http", code:'GET    /api/v1/orders?status=paid&limit=20&cursor=eyJ...\nPOST   /api/v1/orders            { "items": [...] }\nGET    /api/v1/orders/1042\nPATCH  /api/v1/orders/1042       { "status": "shipped" }\nDELETE /api/v1/orders/1042\n\n201 Created\nLocation: /api/v1/orders/1042'},
 dg:"request-response",
 r:["API","HTTP","GraphQL","Status Code","Idempotency","Pagination"]},

{t:"GraphQL", d:"A query language for APIs where the client specifies exactly which fields it wants in a single request.", l:"intermediate", g:["api","architecture"],
 b:["Instead of many fixed endpoints, GraphQL exposes one endpoint and a typed schema. The client sends a query naming precisely the fields it needs, possibly across several related entities, and receives exactly that shape back. This eliminates both over-fetching and the round-trip waterfall.",
    "The costs are real: caching is harder because every query is a POST to the same URL, query complexity must be bounded or a client can request a devastatingly expensive traversal, and naive resolvers create N+1 database queries that DataLoader-style batching must fix."],
 k:["One endpoint, a typed schema, client-specified response shape.",
    "HTTP caching does not apply — you need application-level caching.",
    "Bound query depth and complexity or you have a DoS vector.",
    "Resolvers create N+1 queries without batching."],
 x:{lang:"graphql", code:'query OrderPage($id: ID!) {\n  order(id: $id) {\n    id\n    total\n    customer { name email }\n    items { sku quantity product { title imageUrl } }\n  }\n}'},
 r:["REST","API","N+1 Query Problem","API Gateway"]},

{t:"gRPC", d:"A high-performance RPC framework using Protocol Buffers over HTTP/2.", l:"intermediate", g:["api","architecture"],
 b:["gRPC defines services and messages in a `.proto` file and generates client and server code in a dozen languages. Protocol Buffers are a compact binary format, and HTTP/2 provides multiplexing and streaming, so gRPC is substantially faster and smaller on the wire than JSON over HTTP/1.1.",
    "It excels for internal service-to-service communication where both ends are yours. Browser support requires a proxy (gRPC-Web), and the binary format means you cannot debug it with curl, which is a genuine day-to-day cost."],
 k:["Schema-first: the `.proto` file generates typed clients and servers.",
    "Binary Protobuf over HTTP/2 — compact and fast.",
    "Supports unary, server, client and bidirectional streaming.",
    "Needs a proxy for browsers, and is not human-readable on the wire."],
 x:{lang:"protobuf", code:'syntax = "proto3";\n\nservice OrderService {\n  rpc GetOrder (GetOrderRequest) returns (Order);\n  rpc WatchOrders (WatchRequest) returns (stream Order);\n}\n\nmessage Order {\n  string id    = 1;\n  double total = 2;\n  repeated Item items = 3;\n}'},
 r:["API","REST","Protocol Buffers","Microservices","HTTP"]},

{t:"WebSocket", d:"A protocol providing a persistent, bidirectional connection between client and server over a single TCP link.", l:"core", g:["protocol","realtime"],
 b:["HTTP is request-response: the server cannot speak unless spoken to. A WebSocket upgrades an HTTP connection into a full-duplex channel where either side can send at any time, with minimal per-message overhead. That is what chat, collaborative editing, live dashboards and multiplayer state need.",
    "The operational cost is statefulness: each connection occupies server memory, load balancers must support sticky routing or a shared backplane, and reconnection with state recovery is your responsibility. If only the server needs to push, Server-Sent Events are simpler."],
 k:["Full duplex over one persistent connection after an HTTP upgrade.",
    "Stateful connections complicate load balancing and scaling.",
    "Implement heartbeat, reconnect and backoff yourself.",
    "Use SSE instead when only the server needs to push."],
 r:["Server-Sent Events","HTTP","Load Balancer"]},

{t:"Server-Sent Events", a:"SSE", d:"A one-way stream from server to client over an ordinary HTTP connection.", l:"intermediate", g:["protocol","realtime"],
 b:["SSE keeps an HTTP response open and streams text events as they occur. It is far simpler than WebSocket: it runs over plain HTTP, works through most proxies, and the browser's `EventSource` reconnects automatically and can resume from the last event id.",
    "It is the right tool when only the server sends — notifications, progress updates, live metrics, and LLM token streaming, which is why most chat APIs use it. The limitation is that it is text-only and unidirectional."],
 k:["One-way, server to client, over standard HTTP.",
    "`EventSource` reconnects automatically and supports resume by event id.",
    "Text only — no binary payloads.",
    "The transport behind most streaming LLM APIs."],
 r:["WebSocket","HTTP","Streaming"]},

{t:"Webhook", d:"An HTTP callback where one system pushes an event to a URL you provide, instead of you polling for changes.", l:"core", g:["integration","pattern"],
 b:["Rather than asking every minute whether a payment succeeded, you register a URL and the provider calls it when the event happens. It inverts the direction of integration and removes almost all wasted polling.",
    "Receiving webhooks correctly requires discipline: verify the signature so anyone cannot forge events, respond 2xx quickly and process asynchronously so the sender does not time out, and handle duplicates — delivery is at-least-once, so the same event will arrive twice eventually."],
 k:["Always verify the signature — an unauthenticated endpoint is a forgery vector.",
    "Return 2xx immediately; queue the work rather than processing inline.",
    "Delivery is at-least-once — handle duplicates idempotently.",
    "Events can arrive out of order; use timestamps or sequence numbers."],
 x:{lang:"python",code:"@app.post(\"/webhooks/stripe\")\ndef handle(req):\n    verify_signature(req.headers[\"Stripe-Signature\"], req.body)  # first\n\n    event_id = req.json[\"id\"]\n    if already_processed(event_id):      # duplicates WILL arrive\n        return 200\n    process(req.json)\n    return 200                           # ack fast, work in the background"},
 r:["API","Idempotency","Message Queue","Event-Driven Architecture"]},

{t:"JSON", a:"JavaScript Object Notation", d:"A lightweight text format for structured data, and the default payload format of web APIs.", l:"core", g:["format","data"],
 b:["JSON has six types: object, array, string, number, boolean and null. Its simplicity is why it displaced XML — it is readable, parseable everywhere, and maps directly onto the data structures of most languages.",
    "The gaps matter in practice. There is no date type, so dates travel as ISO 8601 strings by convention. There are no comments. And numbers are IEEE 754 doubles, so integers beyond 2^53 lose precision silently — which is why large ids should be sent as strings."],
 k:["No date type — use ISO 8601 strings.",
    "No comments; JSON5 and JSONC are non-standard extensions.",
    "Integers above 2^53 lose precision — send large ids as strings.",
    "JSON Schema provides validation and documentation."],
 x:{lang:"json",code:"{\n  \"id\": \"1234567890123456789\",\n  \"active\": true,\n  \"score\": 91.5,\n  \"tags\": [\"api\", \"json\"],\n  \"deleted_at\": null,\n  \"created\": \"2026-09-05T10:30:00Z\"\n}"},
 r:["API","REST","Serialisation","YAML","XML"]},

{t:"XML", a:"Extensible Markup Language", d:"A verbose, strongly structured markup format that preceded JSON as the standard for data exchange.", l:"intermediate", g:["format","data"],
 b:["XML supports attributes, namespaces, schemas (XSD) for validation, and transformation via XSLT. That machinery makes it powerful for complex document-oriented data, and it remains standard in SOAP services, finance, publishing, and configuration for older Java tooling.",
    "Its verbosity is the reason JSON replaced it for APIs. It also carries a specific security hazard: XML external entity processing can read local files or make outbound requests unless entity expansion is explicitly disabled in the parser."],
 k:["Attributes, namespaces and schema validation give it more structure than JSON.",
    "Substantially more verbose on the wire.",
    "Disable external entity processing — XXE is a serious vulnerability.",
    "Still standard in SOAP, finance and document publishing."],
 r:["JSON","Serialisation","Markup Language"]},

{t:"YAML", a:"YAML Ain't Markup Language", d:"A human-readable data format used mainly for configuration.", l:"core", g:["format","config"],
 b:["YAML uses indentation instead of brackets, supports comments, and is far easier to read than JSON for nested configuration. Kubernetes manifests, CI pipelines, Docker Compose and Ansible playbooks are all YAML.",
    "Its whitespace sensitivity makes it error-prone — a single wrong indent changes structure silently. It also has surprising type coercion: unquoted `no` becomes false, `1.0` becomes a float, and version numbers like `1.10` lose their trailing zero. Quote ambiguous values."],
 k:["Indentation defines structure — tabs are invalid, use spaces.",
    "Unquoted `yes`, `no`, `on`, `off` become booleans.",
    "Version strings need quoting or they become numbers.",
    "Validate against a schema; YAML errors are silent and structural."],
 r:["JSON","Kubernetes","CI/CD","Infrastructure as Code"]},

{t:"Status Code", a:"HTTP Status Code", d:"The three-digit number in an HTTP response indicating what happened.", l:"core", g:["http","api"],
 b:["The first digit gives the class: 2xx success, 3xx redirection, 4xx client error, 5xx server error. Choosing correctly matters because clients, proxies, caches, monitoring and retry logic all branch on it — returning 200 with an error body inside defeats every one of them.",
    "The distinctions worth knowing: 401 means not authenticated, 403 means authenticated but not permitted; 400 is malformed, 422 is well-formed but semantically invalid; 429 signals rate limiting and should carry `Retry-After`; and 503 with `Retry-After` is the correct response when overloaded."],
 k:["Never return 200 with an error payload — it breaks every consumer.",
    "401 is not authenticated; 403 is authenticated but forbidden.",
    "429 must include `Retry-After` so clients back off correctly.",
    "4xx means do not retry unchanged; 5xx means retry with backoff."],
 x:{lang:"http", code:'200 OK              successful GET or PATCH\n201 Created         + Location header pointing at the new resource\n204 No Content      successful DELETE, empty body\n400 Bad Request     malformed syntax\n401 Unauthorized    missing or invalid credentials\n403 Forbidden       authenticated, but not permitted\n404 Not Found       resource does not exist\n409 Conflict        version conflict, duplicate key\n422 Unprocessable   valid syntax, invalid semantics\n429 Too Many        rate limited; include Retry-After\n500 Server Error    unhandled fault\n503 Unavailable     overloaded or in maintenance'},
 r:["HTTP","REST","API","Rate Limiting","Error Handling"]},

{t:"Pagination", d:"Splitting a large result set into pages so responses stay small and predictable.", l:"core", g:["api","pattern"],
 b:["Offset pagination (`?page=3&limit=20`) is simple but degrades badly: `OFFSET 100000` makes the database scan and discard a hundred thousand rows. It also produces duplicates and gaps when rows are inserted while a client pages through.",
    "Cursor pagination encodes the position of the last item and filters with `WHERE id > cursor`, which uses the index directly and stays fast at any depth. It cannot jump to an arbitrary page, which is the trade — and usually an acceptable one for APIs and infinite scroll."],
 k:["Offset pagination degrades linearly with depth.",
    "Cursor pagination stays O(log n) and is stable under concurrent writes.",
    "Always enforce a maximum page size on the server.",
    "Return the next cursor rather than making clients construct it."],
 x:{lang:"sql", code:'-- offset: scans and throws away 100,000 rows\nSELECT * FROM events ORDER BY id LIMIT 20 OFFSET 100000;\n\n-- cursor (keyset): uses the index, constant cost at any depth\nSELECT * FROM events\nWHERE id > $last_seen_id\nORDER BY id\nLIMIT 20;'},
 r:["REST","API","Index","Query Plan"]},

{t:"API Versioning", d:"Managing changes to an API so existing consumers keep working.", l:"core", g:["api","practice"],
 b:["Adding an optional field or a new endpoint is backward compatible. Removing a field, renaming one, changing a type, or making an optional field required is breaking — and once a third party depends on you, breaking changes require a new version and a deprecation window.",
    "The common approaches are a URL path segment (`/v1/`), a header, or date-based versioning. URL versioning is the most visible and easiest to route. Whatever you choose, publish a deprecation policy and instrument usage so you know who is still on the old version."],
 k:["Adding is safe; removing, renaming and retyping are breaking.",
    "URL versioning is the most explicit and simplest to route.",
    "Publish deprecation timelines and communicate them before removal.",
    "Instrument per-version usage or you can never retire anything."],
 r:["API","REST","Semantic Versioning","Data Contract"]},

{t:"Rate Limiting", d:"Capping how many requests a client may make in a period, to protect a service from overload and abuse.", l:"core", g:["reliability","security"],
 b:["Rate limiting protects against runaway clients, scrapers and denial of service, and it enforces fair use across tenants. The common algorithms are the token bucket (allows bursts up to a capacity, refills at a steady rate), the sliding window (accurate but heavier), and the fixed window (simple but permits double the limit at a boundary).",
    "Return 429 with a `Retry-After` header and expose the current limit and remaining quota in response headers, so well-behaved clients can pace themselves rather than hammering until blocked."],
 k:["Token bucket permits bursts; sliding window is accurate but costlier.",
    "Return 429 with `Retry-After` and rate-limit headers.",
    "Limit per API key or per tenant, not only per IP.",
    "Distributed rate limiting needs shared state, usually Redis."],
 r:["Status Code","Redis","Circuit Breaker","API Gateway"]},

{t:"Authentication", a:"AuthN", d:"Verifying who a caller is.", l:"core", g:["security","identity"],
 b:["Authentication answers are you who you claim to be. The evidence may be something you know (password), something you have (a device, a hardware key) or something you are (biometrics). Combining categories gives multi-factor authentication.",
    "For services, the choice is between session cookies (stateful, easily revoked, ideal for browsers) and tokens such as JWTs (stateless, scalable, harder to revoke). Whatever you choose, hash passwords with bcrypt, scrypt or Argon2, never with a fast hash such as SHA-256."],
 k:["Establishes identity; authorisation then decides permissions.",
    "Hash passwords with bcrypt, scrypt or Argon2 — never SHA or MD5.",
    "Sessions are revocable; JWTs are not without extra machinery.",
    "MFA is the single highest-value security control available."],
 r:["Authorisation","JWT","OAuth 2.0","Session","Multi-Factor Authentication"]},

{t:"Authorisation", a:"AuthZ", d:"Deciding what an authenticated caller is permitted to do.", l:"core", g:["security","identity"],
 b:["Authentication establishes identity; authorisation establishes permission. The common models are role-based access control (permissions attached to roles, roles assigned to users) and attribute-based access control (rules evaluated against attributes of the user, resource and context).",
    "The mistake that causes the most real breaches is checking authorisation in the user interface but not on the server. Hiding a button does not stop anyone calling the endpoint. Every request must be authorised server-side, including for object ownership — the class of bug called insecure direct object reference."],
 k:["Authorise on every request, server-side, without exception.",
    "Hiding UI is not a control — the endpoint is still reachable.",
    "Check object ownership, not only role — IDOR is extremely common.",
    "RBAC for simple hierarchies; ABAC when context matters."],
 r:["Authentication","Role-Based Access Control","Principle of Least Privilege","JWT"]},

{t:"JWT", a:"JSON Web Token", d:"A signed, self-contained token carrying claims about a user, verifiable without a database lookup.", l:"core", g:["security","identity"],
 b:["A JWT is three base64url segments — header, payload, signature — joined by dots. Any service holding the verification key can validate it and read the claims without contacting an auth server, which is what makes it attractive for distributed systems.",
    "The payload is signed, not encrypted, so anyone can read it — never put secrets in it. The critical weakness is revocation: a valid token stays valid until it expires. Use short-lived access tokens (minutes) with refresh tokens, and keep a revocation list for the cases that matter."],
 k:["Signed, not encrypted — the payload is publicly readable.",
    "Cannot be revoked before expiry without server-side state.",
    "Keep access tokens short-lived; use refresh tokens for longevity.",
    "Reject `alg: none` and pin the expected algorithm explicitly."],
 x:{lang:"javascript", code:'const token = jwt.sign(\n  { sub: user.id, role: user.role },\n  process.env.JWT_SECRET,\n  { expiresIn: "15m", issuer: "api.example.com" }\n);\n\n// verification must pin the algorithm\njwt.verify(token, secret, {\n  algorithms: ["HS256"],      // never trust the header alone\n  issuer: "api.example.com",\n});'},
 r:["Authentication","OAuth 2.0","Session","Cookie","Authorisation"]},

{t:"OAuth 2.0", d:"A delegation protocol that lets an application act on a user's behalf without ever seeing their password.", l:"core", g:["security","identity"],
 b:["OAuth solves delegated access: let this app read my calendar. The user authenticates with the provider, consents to specific scopes, and the app receives an access token limited to those scopes. The app never handles the password and access can be revoked independently.",
    "It is an authorisation protocol, not an authentication one — that distinction matters. OpenID Connect is the identity layer built on top of it that adds an ID token describing who the user is. For web applications the authorisation code flow with PKCE is the correct choice."],
 k:["Delegated authorisation — the app never sees the password.",
    "Scopes limit what the token can do; keep them minimal.",
    "OAuth is not authentication — that is OpenID Connect.",
    "Use authorisation code flow with PKCE; implicit flow is deprecated."],
 r:["OpenID Connect","Authentication","JWT","Authorisation","Single Sign-On"]},

{t:"OpenID Connect", a:"OIDC", d:"An identity layer on top of OAuth 2.0 that provides a standard way to verify who a user is.", l:"intermediate", g:["security","identity"],
 b:["OAuth alone tells you an app may access a resource; OIDC adds an ID token — a JWT containing verified claims about the user's identity, such as subject, email and name. That standardisation is what makes sign in with Google or Microsoft work consistently across providers.",
    "The discovery document at `/.well-known/openid-configuration` publishes endpoints and signing keys, so clients configure themselves. Always validate the ID token's signature, issuer, audience and nonce."],
 k:["Adds an ID token with verified identity claims to OAuth's access token.",
    "Discovery document auto-configures endpoints and keys.",
    "Validate signature, issuer, audience and nonce on every ID token.",
    "The standard behind enterprise SSO and social login."],
 r:["OAuth 2.0","JWT","Single Sign-On","Authentication"]},

{t:"Single Sign-On", a:"SSO", d:"Authenticating once with a central identity provider and gaining access to many applications.", l:"intermediate", g:["security","identity"],
 b:["SSO centralises identity. Users authenticate once against an identity provider, which then asserts their identity to each application via SAML or OIDC. Administrators get one place to enforce MFA, one place to offboard a departing employee, and one audit trail.",
    "The trade-off is concentration of risk: a compromised identity provider grants access to everything, and an outage blocks access to everything. Conditional access policies and break-glass accounts address the two respectively."],
 k:["One login, many applications, one place to enforce policy.",
    "Instant offboarding — disable the account and all access ends.",
    "SAML in enterprise, OIDC in newer and consumer systems.",
    "Concentrated risk: protect the identity provider accordingly."],
 r:["OpenID Connect","OAuth 2.0","Authentication","Multi-Factor Authentication"]},

{t:"Session", d:"Server-side state identifying a logged-in user across multiple requests.", l:"core", g:["security","state"],
 b:["The server creates a session record, sends its id to the browser in a cookie, and looks it up on each subsequent request. Because the state lives on the server, logging out, revoking access or changing permissions takes effect immediately — the main advantage over stateless tokens.",
    "Sessions must be stored somewhere shared (Redis or a database) once you run more than one server, or requests will land on an instance that does not recognise the session. Regenerate the session id on login to prevent session fixation."],
 k:["Server holds the state; the cookie holds only an opaque id.",
    "Instant revocation — the main advantage over JWTs.",
    "Shared storage (Redis) is required behind a load balancer.",
    "Regenerate the id on privilege change to prevent fixation."],
 r:["Cookie","JWT","Authentication","Redis","Statelessness"]},

{t:"API Gateway", d:"A single entry point in front of many backend services that handles cross-cutting concerns.", l:"intermediate", g:["architecture","infrastructure"],
 b:["A gateway routes requests to the right service and centralises authentication, rate limiting, TLS termination, request and response transformation, logging and caching. Without one, every service reimplements the same concerns, usually inconsistently.",
    "The risks are that it becomes a single point of failure and, worse, a place where business logic accumulates. Keep it to routing and cross-cutting policy; domain logic belongs in services."],
 k:["Centralises auth, rate limiting, TLS and observability.",
    "Prevents every service reimplementing the same middleware.",
    "Must be highly available — it is on every request path.",
    "Resist putting business logic in it."],
 dg:"monolith-micro",
 r:["Microservices","Load Balancer","Rate Limiting","Reverse Proxy","Service Mesh"]},

{t:"Monolith", d:"An application built and deployed as a single unit.", l:"core", g:["architecture"],
 b:["A monolith has one codebase, one build, one deployment and usually one database. Calls between modules are in-process function calls, so there is no network latency, no partial failure, and transactions across the whole domain work naturally.",
    "It is the correct starting architecture for almost every product. The problems appear at organisational scale — many teams contending over one deployment pipeline, and one module's memory leak taking down everything. A modular monolith with strict internal boundaries postpones that considerably."],
 k:["One deploy, one database, in-process calls, real transactions.",
    "The right default — distribution is a cost you should defer.",
    "Scales technically far further than folklore suggests.",
    "A modular monolith keeps boundaries without adding the network."],
 dg:"monolith-micro",
 r:["Microservices","Modular Monolith","Domain-Driven Design","Horizontal Scaling"]},

{t:"Microservices", d:"An architecture where an application is split into small, independently deployable services.", l:"core", g:["architecture"],
 b:["Each service owns a bounded slice of the domain and its own data, and teams deploy independently. That independence is the real benefit: it is an organisational solution, allowing many teams to ship without coordinating a single release.",
    "The costs are substantial and often underestimated. Every in-process call becomes a network call that can fail, time out or arrive twice. Transactions across services require sagas. Debugging needs distributed tracing. Local development needs orchestration. Do not adopt microservices to solve a technical problem you do not have."],
 k:["Solves an organisational problem — independent team deployment.",
    "Every call can now fail partially, time out, or duplicate.",
    "Cross-service transactions need sagas and eventual consistency.",
    "Requires mature CI/CD, observability and on-call before it pays off."],
 dg:"monolith-micro",
 r:["Monolith","Service Mesh","Saga Pattern","Distributed Tracing","Bounded Context"]},

{t:"Modular Monolith", d:"A single deployable application organised into strictly separated internal modules.", l:"intermediate", g:["architecture","pattern"],
 b:["A modular monolith keeps one deployment but enforces boundaries in the code: modules expose explicit interfaces, do not reach into each other's internals, and ideally do not share database tables. Enforcement can be architectural tests, package visibility, or separate build modules.",
    "It captures most of the maintainability benefit of microservices without the distributed systems tax, and it leaves a clean seam should a module later genuinely need to become a service."],
 k:["One deployment, enforced internal boundaries.",
    "No shared tables between modules — communicate through interfaces.",
    "Enforce boundaries mechanically; conventions alone erode.",
    "Leaves a clean extraction seam for later, if it is ever needed."],
 dg:"monolith-micro",
 r:["Monolith","Microservices","Domain-Driven Design","Bounded Context"]},

{t:"Service Mesh", d:"An infrastructure layer that handles service-to-service communication concerns outside application code.", l:"advanced", g:["architecture","infrastructure"],
 b:["A mesh deploys a sidecar proxy alongside each service instance and routes all inter-service traffic through it. The proxies handle mutual TLS, retries, timeouts, circuit breaking, load balancing, traffic splitting and telemetry — uniformly, without any application changes.",
    "Istio and Linkerd are the main implementations. The cost is significant operational complexity and a small latency and resource overhead per hop, which is why meshes make sense at a few dozen services and are overkill below that."],
 k:["Sidecar proxies intercept all service-to-service traffic.",
    "Provides mTLS, retries, circuit breaking and telemetry uniformly.",
    "No application code changes required.",
    "Real complexity and per-hop overhead — justify it at scale."],
 r:["Microservices","API Gateway","Circuit Breaker","Kubernetes","Distributed Tracing"]},

{t:"Serverless", d:"A model where you deploy functions or containers and the provider manages all servers, scaling and capacity.", l:"core", g:["architecture","cloud"],
 b:["Serverless does not mean no servers; it means no servers you manage. You supply code and configuration, the platform runs it on demand, scales from zero to thousands of concurrent executions, and bills per invocation and per millisecond of execution.",
    "It suits spiky, event-driven and low-baseline workloads exceptionally well. Its constraints are cold starts on the first request after idle, execution time limits, statelessness between invocations, and cost that becomes unattractive at high sustained throughput compared with a reserved instance."],
 k:["Scales to zero — you pay nothing when idle.",
    "Cold starts add latency after periods of inactivity.",
    "Execution time and memory limits constrain what fits.",
    "More expensive than always-on instances at high sustained load."],
 r:["Function as a Service","Cold Start","Autoscaling","Event-Driven Architecture"]},

{t:"Function as a Service", a:"FaaS", d:"Deploying individual functions that run in response to events, with no server management at all.", l:"intermediate", g:["architecture","cloud"],
 b:["AWS Lambda, Cloud Functions and Azure Functions run a single handler triggered by an HTTP request, a queue message, a file upload or a schedule. The platform provisions, scales and tears down execution environments automatically.",
    "The programming model has real constraints: no local state between invocations, a hard timeout, limited deployment package size, and cold starts. Keeping the handler small, initialising expensive clients outside the handler, and using provisioned concurrency for latency-critical paths are the standard mitigations."],
 k:["Event-triggered, stateless, automatically scaled.",
    "Initialise clients outside the handler so they survive warm invocations.",
    "Hard execution timeouts constrain long-running work.",
    "Provisioned concurrency removes cold starts at a cost."],
 r:["Serverless","Cold Start","Event-Driven Architecture","Message Queue"]},

{t:"Event-Driven Architecture", d:"Structuring a system so components communicate by publishing and reacting to events rather than calling each other directly.", l:"intermediate", g:["architecture","pattern"],
 b:["A service publishes an event — `OrderPlaced` — without knowing or caring who consumes it. Consumers subscribe and react. That decoupling means new consumers can be added without touching the producer, and a slow or failed consumer does not block the producer.",
    "The costs are the ones distributed systems always impose: eventual consistency, out-of-order and duplicate delivery, and debugging a flow that has no single call stack. Event schemas need versioning discipline, and consumers must be idempotent."],
 k:["Producers do not know their consumers — that is the decoupling.",
    "Consumers must be idempotent; delivery is at-least-once.",
    "No single call stack — distributed tracing becomes essential.",
    "Event schemas need the same versioning discipline as APIs."],
 r:["Message Queue","Publish-Subscribe","Apache Kafka","Event Sourcing","Idempotency"]},

{t:"Message Queue", d:"A durable buffer that holds messages between a producer and a consumer, decoupling their speeds.", l:"core", g:["infrastructure","pattern"],
 b:["A producer writes messages and returns immediately; consumers read and process at their own rate. That buffering absorbs traffic spikes, survives consumer restarts, and lets you scale consumers independently. RabbitMQ, SQS, Kafka and Redis Streams all serve this role with different guarantees.",
    "Operational essentials: a dead letter queue for messages that repeatedly fail, visibility timeouts so a crashed consumer's message is redelivered, and idempotent consumers because at-least-once delivery guarantees you will process duplicates."],
 k:["Decouples producer and consumer speed; absorbs spikes.",
    "At-least-once delivery is the norm — consumers must be idempotent.",
    "A dead letter queue is mandatory, not optional.",
    "Monitor queue depth and age; growing depth means you are falling behind."],
 dg:"message-queue",
 r:["Publish-Subscribe","Apache Kafka","Event-Driven Architecture","Idempotency","Dead Letter Queue"]},

{t:"Publish-Subscribe", a:"Pub/Sub", d:"A messaging pattern where publishers broadcast to topics and every interested subscriber receives a copy.", l:"core", g:["pattern","messaging"],
 b:["Where a queue delivers each message to exactly one consumer, pub/sub delivers to all subscribers. That is the difference between distributing work and broadcasting a fact. `OrderPlaced` might be consumed independently by billing, inventory, email and analytics.",
    "Kafka blends both: a topic is broadcast across consumer groups, while within a group each partition goes to one consumer. That combination is why it serves both patterns."],
 k:["Every subscriber receives a copy; a queue gives it to exactly one.",
    "Publishers know nothing about subscribers.",
    "Kafka consumer groups combine broadcast with work distribution.",
    "Adding a subscriber requires no producer change."],
 dg:"kafka",
 r:["Message Queue","Apache Kafka","Event-Driven Architecture","Webhook"]},

{t:"Dead Letter Queue", a:"DLQ", d:"A separate queue holding messages that could not be processed after repeated attempts.", l:"intermediate", g:["reliability","messaging"],
 b:["A message that fails repeatedly — malformed payload, a bug, a permanently missing dependency — will otherwise be retried forever, blocking the queue and burning resources. After a configured number of attempts it is moved to a dead letter queue for inspection.",
    "The DLQ is only useful if someone watches it. Alert on non-zero depth, keep the original message plus the failure reason, and provide a replay mechanism once the underlying bug is fixed."],
 k:["Catches poison messages that would otherwise retry indefinitely.",
    "Alert on depth — an unwatched DLQ is a silent data loss channel.",
    "Retain the failure reason alongside the original message.",
    "Provide a tested replay path after fixing the cause."],
 dg:"message-queue",
 r:["Message Queue","Retry","Idempotency","Monitoring"]},

{t:"Event Sourcing", d:"Storing every change as an immutable event, and deriving current state by replaying them.", l:"advanced", g:["architecture","pattern"],
 b:["Instead of updating a row, you append events: `AccountOpened`, `MoneyDeposited`, `MoneyWithdrawn`. Current balance is the fold of those events. You gain a complete audit trail, the ability to reconstruct state at any past moment, and the option to build new projections from history.",
    "The costs are significant. Queries need projections built and maintained separately, event schemas can never be changed retroactively (only versioned), and replaying millions of events requires snapshots. Reserve it for domains where history genuinely matters — finance, compliance, audit."],
 k:["Events are the source of truth; state is a derived projection.",
    "Complete audit trail and time-travel to any historical state.",
    "Events are immutable — schema changes need upcasting or versioning.",
    "Snapshots are required once event counts grow large."],
 r:["CQRS","Event-Driven Architecture","Apache Kafka","Audit Log"]},

{t:"CQRS", a:"Command Query Responsibility Segregation", d:"Separating the model used for writes from the model used for reads.", l:"advanced", g:["architecture","pattern"],
 b:["Writes go through a command model enforcing invariants; reads come from a separate model shaped for querying — often denormalised, sometimes in a different database entirely. The two are kept in sync, usually asynchronously.",
    "This lets each side be optimised independently: normalised and consistent for writes, denormalised and fast for reads. The costs are eventual consistency between them and a great deal more machinery. It pays off when read and write loads differ enormously; otherwise it is overhead."],
 k:["Separate models for writing and reading, optimised differently.",
    "Read models are typically denormalised and eventually consistent.",
    "Often paired with event sourcing, but independent of it.",
    "Justified by a large asymmetry between read and write load."],
 r:["Event Sourcing","Denormalisation","Eventual Consistency","Materialised View"]},

{t:"Saga Pattern", d:"Managing a transaction that spans several services as a sequence of local transactions with compensating actions.", l:"advanced", g:["architecture","pattern"],
 b:["A distributed transaction across services is impractical, so a saga breaks the workflow into local transactions, each publishing an event that triggers the next. If a later step fails, previously completed steps are undone by explicit compensating transactions — refund the payment, release the inventory.",
    "Choreography has each service react to events with no central coordinator, which is simple until the flow grows. Orchestration uses an explicit coordinator, which is easier to reason about and to debug. Compensations are business logic, not rollback — you cannot un-send an email."],
 k:["No distributed transaction — local transactions plus compensations.",
    "Compensating actions are business operations, not database rollbacks.",
    "Choreography scales poorly in complexity; orchestration is easier to debug.",
    "Intermediate states are visible — design the domain to tolerate that."],
 r:["Microservices","Event-Driven Architecture","Eventual Consistency","Transaction"]},

{t:"Domain-Driven Design", a:"DDD", d:"Structuring software around a rigorous model of the business domain, expressed in the language the business uses.", l:"advanced", g:["architecture","practice"],
 b:["DDD's strategic patterns matter most: identify bounded contexts where a term has one consistent meaning, map the relationships between them, and build a ubiquitous language shared by developers and domain experts. Its tactical patterns — entities, value objects, aggregates, repositories — implement that model in code.",
    "The core insight is that most software failures are modelling failures, not technical ones. When `customer` means three different things in three parts of the system and they share one class, complexity compounds."],
 k:["Bounded context: where a term has exactly one meaning.",
    "Ubiquitous language shared by engineers and domain experts.",
    "Aggregates define transactional consistency boundaries.",
    "Bounded contexts are the natural seams for service boundaries."],
 r:["Bounded Context","Microservices","Modular Monolith","Hexagonal Architecture"]},

{t:"Bounded Context", d:"A boundary within which a domain model and its terminology are internally consistent.", l:"advanced", g:["architecture","ddd"],
 b:["In sales, a customer is a prospect with a pipeline stage. In support, a customer is an account with tickets. In billing, a customer is a payer with an address. Forcing one shared model produces a class with forty fields that serves nobody well.",
    "A bounded context lets each area define its own model. Translation happens explicitly at the boundary via an anti-corruption layer. This is why bounded contexts are the right basis for service decomposition — they are where the coupling is genuinely low."],
 k:["One consistent model and vocabulary inside each boundary.",
    "The same real-world entity is modelled differently in each context.",
    "Anti-corruption layers translate between contexts explicitly.",
    "The correct seam for splitting services."],
 r:["Domain-Driven Design","Microservices","Modular Monolith"]},

{t:"Hexagonal Architecture", a:"Ports and Adapters", d:"Isolating domain logic from external systems behind interfaces, so infrastructure can be swapped without touching the core.", l:"advanced", g:["architecture","pattern"],
 b:["The domain defines ports — interfaces describing what it needs, such as `OrderRepository` or `PaymentGateway`. Adapters implement them against real infrastructure: Postgres, Stripe, an HTTP client. Dependencies point inward, so the domain knows nothing about the database or the web framework.",
    "The payoff is testability and longevity. Domain logic is tested with in-memory adapters and no infrastructure at all, and replacing a database or a payment provider touches only the adapter. Clean architecture and onion architecture are variations on the same principle."],
 k:["Dependencies point inward; the domain depends on nothing external.",
    "Ports are interfaces the domain owns; adapters implement them.",
    "Domain tests need no database, network or framework.",
    "Clean and onion architecture are the same idea, differently named."],
 r:["Dependency Injection","Domain-Driven Design","Interface","Unit Test"]},

{t:"Dependency Injection", a:"DI", d:"Supplying a component's dependencies from outside rather than letting it construct them itself.", l:"core", g:["pattern","design"],
 b:["Instead of a service creating its own database client, the client is passed into its constructor. That inverts control: the caller decides what to supply, so tests can supply a fake and production can supply the real thing without changing the class.",
    "A framework is not required — constructor injection is just passing arguments. DI containers help in large codebases by wiring object graphs automatically, but they also add indirection that can make control flow hard to follow."],
 k:["Dependencies passed in, not constructed internally.",
    "Makes testing straightforward — substitute a fake at the boundary.",
    "Constructor injection is the clearest form and needs no framework.",
    "Containers help at scale but obscure control flow."],
 x:{lang:"python", code:'class OrderService:\n    def __init__(self, repo: OrderRepository, payments: PaymentGateway):\n        self.repo = repo\n        self.payments = payments\n\n# production\nsvc = OrderService(PostgresOrderRepo(pool), StripeGateway(key))\n\n# test — no database, no network\nsvc = OrderService(InMemoryOrderRepo(), FakeGateway())'},
 r:["Hexagonal Architecture","Interface","Unit Test","Composition over Inheritance"]},

{t:"Middleware", d:"A function in a request-handling pipeline that runs before or after the main handler.", l:"core", g:["pattern","backend"],
 b:["Middleware handles cross-cutting concerns: logging, authentication, compression, CORS headers, request ids, error handling. Each piece receives the request, may modify it, and either passes control onward or short-circuits with a response.",
    "Order matters and is a frequent source of bugs. Error-handling middleware must be registered last to catch everything; authentication must run before authorisation; body parsing must precede anything that reads the body."],
 k:["Composable pipeline around the request handler.",
    "Registration order determines execution order — and it matters.",
    "Error handlers go last so they catch everything before them.",
    "Short-circuit early for auth failures and rate limits."],
 r:["API","Authentication","Rate Limiting","Higher-Order Function"]},

{t:"Load Balancer", d:"A component that distributes incoming traffic across multiple backend instances.", l:"core", g:["infrastructure","scaling"],
 b:["A load balancer spreads requests across healthy instances and removes unhealthy ones from rotation based on health checks. That gives both horizontal scale and availability — one instance failing does not take the service down.",
    "Layer 4 balancers route on IP and port and are extremely fast. Layer 7 balancers read HTTP and can route by path, host or header, terminate TLS and rewrite requests. Round robin, least connections and consistent hashing are the common algorithms."],
 k:["Health checks are what make it a availability mechanism, not just a splitter.",
    "L4 routes on TCP; L7 understands HTTP and can route on content.",
    "Least connections handles uneven request durations better than round robin.",
    "Consistent hashing keeps a given key on the same backend."],
 dg:"load-balancer",
 r:["Reverse Proxy","Horizontal Scaling","Health Check","Sticky Session","API Gateway"]},

{t:"Reverse Proxy", d:"A server that receives client requests and forwards them to backend servers, presenting itself as the origin.", l:"core", g:["infrastructure","networking"],
 b:["A forward proxy sits in front of clients; a reverse proxy sits in front of servers. It terminates TLS, serves static files, compresses responses, caches, rate limits, and hides the internal topology — clients only ever see the proxy.",
    "Nginx, HAProxy, Caddy and Envoy are the common implementations. Load balancers are a subset of reverse proxies, and API gateways are reverse proxies with more application awareness."],
 k:["Sits in front of servers; a forward proxy sits in front of clients.",
    "Terminates TLS, compresses, caches and serves static assets.",
    "Hides internal topology and provides a single public entry point.",
    "Load balancers and API gateways are specialised reverse proxies."],
 r:["Load Balancer","API Gateway","CDN","TLS","Caching"]},

{t:"Caching", d:"Storing the result of an expensive operation so subsequent requests can be served from the copy.", l:"core", g:["performance","architecture"],
 b:["Caches exist at every layer: CPU, browser, CDN, reverse proxy, application memory, Redis, and the database's own buffer pool. Each turns a slow computation or query into a fast lookup, and a good cache hit ratio is often the difference between a service that scales and one that does not.",
    "The two hard problems are invalidation — knowing when a cached value is stale — and stampedes, where a popular key expires and a thousand concurrent requests all miss and hit the database simultaneously. Locking, staggered TTLs and serving stale while revalidating are the standard defences."],
 k:["Every layer caches: browser, CDN, proxy, application, database.",
    "Invalidation is genuinely hard — prefer short TTLs over clever schemes.",
    "Cache stampedes need request coalescing or staggered expiry.",
    "Measure hit ratio; a cache below ~80% hits may not be earning its complexity."],
 dg:"caching",
 r:["Cache Invalidation","CDN","Redis","Latency","Materialised View"]},

{t:"Cache Invalidation", d:"Removing or refreshing cached data once the underlying source has changed.", l:"intermediate", g:["performance","architecture"],
 b:["The strategies are time-based expiry (a TTL — simple and predictable, but serves stale data for its duration), event-based invalidation (delete the key when the source changes — precise, but every write path must remember), and versioned keys (include a version in the key so old entries are simply never read again).",
    "Versioned keys are underused and elegant: no deletion is required, old entries age out naturally, and there is no window where a stale value can be served."],
 k:["TTL is simple and predictable; event-based is precise and fragile.",
    "Versioned cache keys avoid deletion entirely.",
    "Stale-while-revalidate serves the old value while refreshing in the background.",
    "Cache-aside is the common pattern: check cache, miss, load, store."],
 r:["Caching","CDN","Redis","Eventual Consistency"]},

{t:"CDN", a:"Content Delivery Network", d:"A geographically distributed network of servers that caches content close to users.", l:"core", g:["infrastructure","performance"],
 b:["A CDN serves assets from an edge location near the user rather than from a single origin, cutting round-trip latency from hundreds of milliseconds to tens. It also absorbs traffic spikes and mitigates DDoS attacks by soaking up volume before it reaches the origin.",
    "Static assets are the obvious use, but modern CDNs also cache API responses, run edge functions and terminate TLS. Cache-busting via content-hashed filenames lets you set very long TTLs safely."],
 k:["Serves from the nearest edge, cutting latency dramatically.",
    "Absorbs traffic spikes and DDoS volume before it reaches origin.",
    "Content-hashed filenames allow immutable long-TTL caching.",
    "Edge compute runs logic close to users, not just static files."],
 r:["Caching","Reverse Proxy","Latency","Static Site Generation","Denial of Service"]},

{t:"Horizontal Scaling", a:"Scaling Out", d:"Adding more machines to share the load, rather than making one machine bigger.", l:"core", g:["scaling","architecture"],
 b:["Horizontal scaling adds instances behind a load balancer. It has no hard ceiling, it improves availability because one machine failing is survivable, and it works with commodity hardware. It is the model cloud infrastructure is built around.",
    "It requires the application to be stateless, or to keep shared state in an external store. Any in-memory session data, local file uploads or in-process caches break the moment a second instance appears."],
 k:["No practical ceiling; improves availability as a side effect.",
    "Requires statelessness or externalised shared state.",
    "In-memory sessions and local file writes break under it.",
    "Databases are harder to scale out than application servers."],
 dg:"load-balancer",
 r:["Vertical Scaling","Statelessness","Load Balancer","Autoscaling","Sharding"]},

{t:"Vertical Scaling", a:"Scaling Up", d:"Making a single machine more powerful — more CPU, memory or faster storage.", l:"core", g:["scaling","architecture"],
 b:["Vertical scaling requires no architectural change: resize the instance and restart. For databases especially it is often the correct first answer, because a machine with a terabyte of memory solves a great many problems that sharding would solve at much greater complexity.",
    "The limits are a hardware ceiling, cost that rises non-linearly at the top end, and the fact that one machine remains a single point of failure. Scale up until it stops being economical, then scale out."],
 k:["No code changes needed — the simplest form of scaling.",
    "Hardware ceiling, and cost rises steeply at the high end.",
    "Still a single point of failure.",
    "Usually the right first answer for databases."],
 r:["Horizontal Scaling","Sharding","Autoscaling"]},

{t:"Statelessness", d:"Designing a service so no request depends on information held in that particular instance's memory.", l:"core", g:["architecture","scaling"],
 b:["A stateless service can handle any request on any instance, because everything needed is in the request itself or in shared external storage. That is what makes horizontal scaling, rolling deployments, autoscaling and instance replacement straightforward.",
    "State still exists — it moves to a database, Redis, or object storage. The discipline is keeping it out of instance memory and off the local disk, where it becomes invisible coupling that fails the moment you add a second instance."],
 k:["Any instance can serve any request.",
    "Enables autoscaling, rolling deploys and instance replacement.",
    "State moves to a shared store, it does not disappear.",
    "Local disk writes and in-memory sessions break statelessness."],
 r:["Horizontal Scaling","Session","Load Balancer","Twelve-Factor App"]},

{t:"Sticky Session", a:"Session Affinity", d:"Routing a client's requests consistently to the same backend instance.", l:"intermediate", g:["scaling","networking"],
 b:["Sticky sessions let a stateful application work behind a load balancer by pinning each client to one instance, usually via a cookie or a hash of the client IP. It is the pragmatic fix when the application keeps session state in memory.",
    "It also undermines most of the benefits of load balancing: load distributes unevenly, deploying an instance drops its sessions, and autoscaling cannot rebalance existing traffic. Externalising session state is the better answer wherever it is feasible."],
 k:["Pins a client to one instance, usually by cookie or IP hash.",
    "A workaround for in-memory state, not a design goal.",
    "Causes uneven load and session loss on deployment.",
    "Externalising sessions to Redis is the durable fix."],
 r:["Load Balancer","Session","Statelessness","Horizontal Scaling"]},

{t:"Circuit Breaker", d:"A pattern that stops calling a failing dependency for a period, so failures do not cascade.", l:"intermediate", g:["reliability","pattern"],
 b:["A circuit breaker counts failures. Past a threshold it opens, and further calls fail immediately without attempting the network — which protects the caller's threads, avoids piling load onto a struggling dependency, and gives it room to recover. After a timeout it half-opens to test with a single request.",
    "Without one, a slow dependency exhausts the caller's connection pool and thread pool, and the failure propagates upward through every service that depends on it. That is how one struggling service takes down an entire platform."],
 k:["Three states: closed, open, half-open.",
    "Fails fast when open, protecting caller resources.",
    "Prevents a single slow dependency from cascading across a platform.",
    "Always pair with a sensible fallback behaviour."],
 r:["Retry","Timeout","Graceful Degradation","Microservices","Bulkhead"]},

{t:"Retry", d:"Automatically reattempting a failed operation, on the assumption the failure was transient.", l:"core", g:["reliability","pattern"],
 b:["Network blips, brief timeouts, throttling responses and leader elections are transient — retrying works. Validation errors, 401s and 404s are not, and retrying them wastes resources and can worsen an incident.",
    "Retries must be bounded, must use exponential backoff with jitter, and must only be applied to idempotent operations. Naive immediate retries across many clients synchronise into a thundering herd that turns a brief hiccup into an outage."],
 k:["Retry 5xx, timeouts and 429; never retry 4xx validation errors.",
    "Exponential backoff with jitter, and a hard attempt limit.",
    "Only safe for idempotent operations.",
    "Unjittered retries synchronise and amplify the original failure."],
 r:["Exponential Backoff","Idempotency","Circuit Breaker","Timeout","Status Code"]},

{t:"Exponential Backoff", d:"Increasing the wait between retry attempts exponentially, with randomness added.", l:"intermediate", g:["reliability","pattern"],
 b:["Wait 1 second, then 2, then 4, then 8, capped at some maximum. This gives a struggling dependency progressively more room to recover instead of hammering it at a constant rate.",
    "Jitter is the essential and frequently omitted half. Without random variation, every client that failed at the same moment retries at the same moment, producing synchronised waves of load. Full jitter — a random value between zero and the computed delay — is the standard recommendation."],
 k:["Delay doubles each attempt, capped at a maximum.",
    "Jitter is essential — without it retries synchronise into waves.",
    "Full jitter (random between 0 and the delay) is the usual choice.",
    "Always set a total attempt or total time budget."],
 r:["Retry","Circuit Breaker","Rate Limiting","Timeout"]},

{t:"Timeout", d:"A limit on how long an operation may take before it is abandoned.", l:"core", g:["reliability","pattern"],
 b:["Every network call needs a timeout. Without one, a hung dependency holds a connection and a thread indefinitely, and enough of those exhaust the pool and take the service down — a failure mode that looks like a hang rather than an error, which makes it harder to diagnose.",
    "Timeouts must form a budget: if the caller allows 2 seconds total, downstream calls must total less than that, or you time out at every layer simultaneously and waste all the work. Set connect and read timeouts separately."],
 k:["Every network call needs an explicit timeout — defaults are often infinite.",
    "Budget timeouts downward through the call chain.",
    "Set connect and read timeouts separately.",
    "Missing timeouts present as hangs and thread pool exhaustion."],
 r:["Retry","Circuit Breaker","Latency Budget","Connection Pool"]},

{t:"Bulkhead", d:"Isolating resources so failure in one part of a system cannot consume everything.", l:"advanced", g:["reliability","pattern"],
 b:["Named after ship compartments, the bulkhead pattern partitions resources — separate thread pools, connection pools or instance groups per dependency or per tenant. If one downstream service becomes slow, only its pool is exhausted; the rest of the application continues.",
    "Without bulkheads, a single slow dependency consumes every thread in a shared pool, and requests that never touch that dependency start failing too."],
 k:["Partition thread and connection pools per dependency or tenant.",
    "Contains failure instead of letting it consume shared resources.",
    "Prevents one slow dependency from failing unrelated requests.",
    "Complements circuit breakers rather than replacing them."],
 r:["Circuit Breaker","Timeout","Connection Pool","Graceful Degradation"]},

{t:"Graceful Degradation", d:"Continuing to provide reduced but useful service when a dependency fails.", l:"intermediate", g:["reliability","design"],
 b:["If the recommendation service is down, show popular items instead of an error page. If personalisation fails, render the generic version. If the search index is unavailable, fall back to a database query. The core function keeps working while the enhancement is missing.",
    "This requires deciding in advance which dependencies are critical and which are optional, and building explicit fallbacks for the optional ones. Systems that treat every dependency as critical fail entirely whenever any single component does."],
 k:["Classify dependencies as critical or optional, deliberately.",
    "Optional dependencies need explicit, tested fallbacks.",
    "Serving stale cached data usually beats serving an error.",
    "Feature flags allow shedding non-essential load under pressure."],
 r:["Circuit Breaker","Caching","Feature Flag","Bulkhead"]},

{t:"Health Check", d:"An endpoint that reports whether a service instance is able to handle traffic.", l:"core", g:["reliability","operations"],
 b:["Load balancers and orchestrators poll health endpoints to decide whether to route traffic to an instance. Kubernetes distinguishes liveness (is the process wedged and in need of restart) from readiness (is it able to serve right now) — conflating them causes restart loops.",
    "A readiness check should verify critical dependencies; a liveness check should not, or a brief database outage will cause every pod to be killed and restarted simultaneously, turning a recoverable problem into an outage."],
 k:["Liveness means restart me; readiness means route to me.",
    "Never check external dependencies in a liveness probe.",
    "Readiness should fail during startup and graceful shutdown.",
    "Keep the check cheap — it runs every few seconds forever."],
 r:["Load Balancer","Kubernetes","Monitoring","Graceful Degradation"]},

{t:"Twelve-Factor App", d:"A set of twelve principles for building applications suited to cloud deployment.", l:"intermediate", g:["practice","architecture"],
 b:["The factors cover configuration in the environment rather than in files, explicit dependency declaration, treating backing services as attachable resources, strict separation of build and run stages, stateless processes, logs as event streams to stdout, and disposability with fast startup and graceful shutdown.",
    "Written in 2011, most of it aged extremely well — it describes exactly what containers and orchestrators expect. The main modern amendment is around configuration secrets, which belong in a secret manager rather than plain environment variables."],
 k:["Configuration in the environment, never committed to the repository.",
    "Stateless, disposable processes with fast startup and clean shutdown.",
    "Logs to stdout as an event stream; the platform handles routing.",
    "Strict separation of build, release and run stages."],
 r:["Statelessness","Container","Configuration Management","Secrets Management"]},

{t:"Backend for Frontend", a:"BFF", d:"A dedicated backend service tailored to the needs of one specific client application.", l:"advanced", g:["architecture","pattern"],
 b:["A mobile app and a web app want different data shapes, different payload sizes and different aggregation. Rather than making one general API serve both badly, a BFF sits between each client and the downstream services, aggregating and shaping responses for that client alone.",
    "It removes over-fetching and reduces round trips on mobile. The cost is another service per client platform to build, deploy and keep in sync — worth it when clients genuinely diverge, wasteful when they do not."],
 k:["One backend per client type, owned by the client team.",
    "Aggregates downstream calls and shapes the response for that client.",
    "Reduces over-fetching and mobile round trips.",
    "Adds a service per platform — justify the divergence first."],
 r:["API Gateway","Microservices","GraphQL","API"]},

{t:"Feature Flag", a:"Feature Toggle", d:"A runtime switch that turns functionality on or off without deploying new code.", l:"core", g:["practice","deployment"],
 b:["Feature flags decouple deployment from release. Code ships dark, is enabled for internal users, then a percentage of traffic, then everyone — and can be switched off instantly if something goes wrong, without a rollback.",
    "They also enable trunk-based development, since incomplete features can be merged behind a disabled flag. The discipline that matters is removing flags once a feature is fully released; long-lived flags multiply code paths and become permanent technical debt."],
 k:["Separates deploying code from releasing behaviour.",
    "Instant kill switch without a rollback or redeploy.",
    "Enables trunk-based development and progressive rollout.",
    "Remove flags promptly — each one doubles the paths to test."],
 x:{lang:"python",code:"if flags.enabled(\"new_checkout\", user):\n    return new_checkout(user)\nreturn old_checkout(user)\n\n# rollout:  staff -> 1% -> 10% -> 100%\n# rollback: flip the flag. No deploy, no build, seconds.\n# then:     delete the flag AND the old branch"},
 r:["Canary Deployment","A/B Testing","Graceful Degradation"]},

{t:"Distributed System", d:"A system whose components run on separate networked machines and coordinate by passing messages.", l:"intermediate", g:["architecture","theory"],
 b:["Distribution buys scale and fault tolerance and introduces an entirely new failure model. Messages can be lost, delayed, duplicated or reordered; a node can be slow rather than dead and you cannot tell the difference; and there is no global clock, so ordering events across machines is genuinely hard.",
    "The classic fallacies — the network is reliable, latency is zero, bandwidth is infinite, topology does not change — describe assumptions that seem obviously false written down and that engineers make implicitly all the time."],
 k:["Partial failure is the defining difficulty — some parts work, others do not.",
    "You cannot distinguish a slow node from a dead one.",
    "No global clock; use logical clocks for ordering.",
    "The eight fallacies of distributed computing are all assumptions people still make."],
 r:["CAP Theorem","Microservices","Consensus","Eventual Consistency","Idempotency"]},

{t:"Consensus", d:"Getting a group of distributed nodes to agree on a single value despite failures.", l:"advanced", g:["distributed","theory"],
 b:["Consensus algorithms — Paxos, Raft, Zab — let a cluster agree on an ordered log of decisions even when some nodes crash or messages are lost. This is what underpins leader election, distributed locks, configuration stores and replicated state machines.",
    "They require a majority quorum, so a cluster of five tolerates two failures. That is also why cluster sizes are odd: six nodes tolerate the same two failures as five while costing more. Raft was designed specifically to be easier to understand than Paxos, and is what etcd and Consul implement."],
 k:["Requires a majority quorum — an n-node cluster tolerates ⌊(n−1)/2⌋ failures.",
    "Odd cluster sizes: 5 nodes tolerate the same failures as 6.",
    "Raft is the comprehensible one; etcd and Consul use it.",
    "Consensus is expensive — avoid it on the hot path."],
 r:["Distributed System","Leader Election","CAP Theorem","Kubernetes"]},

{t:"Leader Election", d:"Choosing one node in a cluster to coordinate work that must not happen concurrently.", l:"advanced", g:["distributed","pattern"],
 b:["Many tasks must run exactly once — a scheduled job, a partition assignment, a write to a primary. Leader election designates one node to do them, and re-elects when that node fails. It is typically built on a consensus system or a distributed lock with a lease.",
    "The dangerous failure is split brain: a network partition leaves two nodes each believing they are leader, and both write. Fencing tokens — a monotonically increasing number checked by downstream systems — prevent a stale leader's writes from being accepted."],
 k:["Ensures exactly one coordinator for work that must not run twice.",
    "Split brain is the critical failure mode under network partition.",
    "Leases must be renewed; expiry triggers re-election.",
    "Fencing tokens stop a stale leader's writes being accepted."],
 r:["Consensus","Distributed System","Kubernetes","CAP Theorem"]},

{t:"Cron Job", d:"A task scheduled to run automatically at fixed times or intervals.", l:"core", g:["operations","pattern"],
 b:["Cron expressions define a schedule in five or six fields: minute, hour, day of month, month, day of week. Cron jobs handle reports, cleanups, syncs, backups and batch processing.",
    "The operational failure modes are consistent and avoidable: overlapping runs when a job takes longer than its interval, silent failures because nobody monitors success, time zone and daylight saving confusion, and a job that only runs on one machine which happens to be down. Locking, alerting on missed runs, and running in UTC address all four."],
 k:["Prevent overlapping runs with a lock — long jobs will overlap eventually.",
    "Alert on missed runs, not only on failed ones.",
    "Run schedules in UTC; daylight saving causes skipped and doubled runs.",
    "Make jobs idempotent so a rerun is always safe."],
 r:["Idempotency","Apache Airflow","Batch Processing","Monitoring"]},

{t:"Protocol Buffers", a:"Protobuf", d:"Google's compact binary serialisation format with a schema-first definition language.", l:"intermediate", g:["format","serialisation"],
 b:["You define messages in a `.proto` file and a compiler generates typed classes for each language. The wire format identifies fields by number rather than name, which makes it compact and allows fields to be renamed freely without breaking compatibility.",
    "Field numbers are the contract and must never be reused after a field is removed — reserve them instead. Adding optional fields is backward compatible, which is what makes protobuf good for long-lived service interfaces."],
 k:["Field numbers, not names, are the wire contract — never reuse them.",
    "Adding optional fields is backward compatible.",
    "Substantially smaller and faster to parse than JSON.",
    "Not human-readable — a genuine debugging cost."],
 r:["gRPC","Serialisation","Avro","Schema Evolution","JSON"]},

{t:"Error Handling", d:"How a program detects, communicates and recovers from failures.", l:"core", g:["practice","reliability"],
 b:["The approaches differ by language: exceptions that propagate up the stack, error values returned alongside results, or result types that force the caller to handle both cases. Each makes different failure modes hard to ignore.",
    "The practices that matter are consistent across all of them: never swallow an error silently, include enough context to diagnose the problem, distinguish expected failures (validation, not found) from unexpected ones (bugs, infrastructure faults), and never leak internal details such as stack traces or SQL to end users."],
 k:["Never catch an exception and do nothing — that is how bugs become invisible.",
    "Attach context as errors propagate; a bare message is useless.",
    "Separate expected failures from genuine bugs in both logging and alerting.",
    "Return generic messages to users, detailed ones to logs."],
 r:["Status Code","Logging","Retry","Observability"]}

]);
